import { create_list_delete_sub_tags } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import EditSubcategories from "@/components/Asset/Popups/EditSubcategories.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  props: {
    addSubTagDialog: Boolean,
    rowInfo: Object
  },
  components: {
    EditSubcategories,
    SnackBar
  },
  data() {
    return {
      subtagName: "",
      fixed: false,
      SnackBarComponent: {},
      headers: [{
        title: "Types",
        key: "sub_tag_name",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      subTagData: [],
      tableLoading: false,
      deleteItem: {}
    };
  },
  watch: {
    addSubTagDialog: {
      async handler() {
        if (this.addSubTagDialog == true) {
          // console.log(this.rowInfo, "rowInfo");

          await this.fetch_ssub_tags("LIST");
          this.tableLoading = false;
          //   this.fetch_sub_data();
        }
      },
      immediate: true
    }
  },
  methods: {
    async fetch_ssub_tags(value) {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_delete_sub_tags, {
          input: {
            user_email_id: data.user.user_email_id,
            sub_tag_name: value == "CREATE" ? this.subtagName : undefined,
            action_type: value,
            tag_id: this.rowInfo.tag_id,
            sub_tag_id: value == "DELETE" ? this.deleteItem.sub_tag_id : undefined,
            sub_tag_status: value == "DELETE" ? "DEACTIVE" : undefined
          }
        }));
        var response = JSON.parse(result.data.create_list_delete_sub_tags);
        this.tableLoading = false;
        this.loading = false;
        this.subTagData = [];
        if (response.Status == "SUCCESS") {
          if (value == "CREATE" || value == "DELETE") {
            this.tableLoading = false;
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "green",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
            this.loading = false;
            this.$refs.form.reset();
            this.subtagName = "";
            this.fetch_ssub_tags("LIST");
          } else if (value == "LIST") {
            this.tableLoading = false;
            this.subTagData = response.data;
          }
          // this.$emit("updaterefesh", "update");
        } else {
          this.tableLoading = false;
          this.loading = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.tableLoading = false;
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    open_edit_dailog(item) {
      this.componentCheck = 1;
      this.categoriessubEddition = true;
      this.categoriesItem = item;
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.selectedSubCategory = [];
      this.categoriessubEddition = false;
      await this.get_asset_sub_categories();
      this.tableLoading = false;
      this.fetch_sub_data();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async delete_data(item) {
      this.deleteItem = item;
      await this.fetch_ssub_tags("DELETE");
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.categoryPrefix = "";
      this.categoriesName = "";
      // this.$refs.form.reset();
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.loading = true;
        this.fetch_ssub_tags("CREATE");
      }
    }
  }
};
